/* From Uiverse.io by escannord  - Tags: simple, blue, plus, pattern */
.__UIV_SCOPE__ .container {
  width: 100%;
  height: 100%;
  /* Add your background pattern here */
  background: rgb(57, 59, 59);
  background: radial-gradient(
    circle at 50%,
    rgb(41, 39, 39),
    #333 50%,
    transparent 51%,
    #eee 10%,
    rgb(0, 0, 0) 55% 72%,
    rgb(15, 96, 189) 50%
  );
  background-size: 10px 10px;
}
